<?php namespace App\Notifications; use Illuminate\Bus\Queueable; use Illuminate\Notifications\Notification; use Illuminate\Support\Str; class NewKomplainNotification extends Notification { use Queueable; public $komplain; public function __construct($komplain) { $this->komplain = $komplain; } public function via($notifiable) { return ['database']; } public function toArray($notifiable) { return [ 'type' => 'komplain', 'title' => 'Komplain Fasilitas Baru', 'message' => $this->komplain->reservasi->tamu->nama . ' melaporkan: ' . Str::limit($this->komplain->deskripsi, 50), 'url' => route('admin.komplain') ]; } }